Record::Record(Block value, Record *previous, Utxo coins, std::vector<Integer> amounts, std::string origin)
    : block(std::move(value)), parent(previous), utxo(std::move(coins)), transaction_fees(std::move(amounts)),
      source(std::move(origin)) {
    fees = std::accumulate(transaction_fees.begin(), transaction_fees.end(), Integer(0));
    if (parent)
        work = parent->work + (Integer(1) << (4 * block.difficulty));
}
Record *ancestor(Record *record, int height) {
    while (record->block.height > height)
        record = record->parent;
    return record;
}
std::vector<Record *> chain_to(Record *record) {
    std::vector<Record *> result;
    for (; record; record = record->parent)
        result.push_back(record);
    std::reverse(result.begin(), result.end());
    return result;
}
Record *fork_point(Record *a, Record *b) {
    const int height = std::min(a->block.height, b->block.height);
    a = ancestor(a, height);
    b = ancestor(b, height);
    while (a != b) {
        a = a->parent;
        b = b->parent;
    }
    return a;
}
std::string Block::header() const {
    return std::to_string(height) + "|" + previous + "|" + root + "|" + std::to_string(time) + "|" +
           std::to_string(difficulty) + "|" + std::to_string(nonce);
}
void Block::hash_header() {
    hash = digest(header());
}
Integer Block::size() const {
    Integer size = 0;
    for (std::size_t i = 1; i < transactions.size(); ++i)
        size += transactions[i].size();
    return size;
}
bool Block::proof() const {
    return hash.compare(0, difficulty, std::string(difficulty, '0')) == 0;
}
Block parse_block(const std::vector<std::string> &fields, const std::vector<std::string> &texts) {
    Block block;
    block.height = std::stoi(fields[3]);
    block.previous = fields[4];
    block.root = fields[5];
    block.time = std::stoll(fields[6]);
    block.difficulty = std::stoi(fields[7]);
    block.nonce = std::stoll(fields[8]);
    for (const std::string &text : texts)
        block.transactions.push_back(parse_transaction(text));
    block.hash_header();
    return block;
}
std::string context_error(const Block &block, Integer limit) {
    if (!block.proof())
        return "bad-pow";
    std::vector<std::string> ids;
    for (const Transaction &tx : block.transactions)
        ids.push_back(tx.id);
    if (merkle(ids) != block.root)
        return "bad-merkle";
    if (!block.transactions[0].coinbase() || block.transactions[0].coinbase_height != block.height)
        return "bad-structure";
    for (std::size_t i = 1; i < block.transactions.size(); ++i)
        if (block.transactions[i].coinbase())
            return "bad-structure";
    return block.size() > limit ? "too-large" : "";
}
bool Coin::mature(int at, int maturity) const {
    return !coinbase || height == 0 || at >= height + maturity;
}
Integer Transaction::total() const {
    Integer amount = 0;
    for (const Output &output : outputs)
        amount += output.second;
    return amount;
}
std::pair<std::string, Integer> check_transaction(const Transaction &tx, const Utxo &utxo,
                                                  const std::set<Reference> &spent, int height,
                                                  const Owners &owners, int maturity) {
    for (const Output &output : tx.outputs)
        if (!owners.count(output.first) || output.second == 0)
            return {"bad-output", 0};
    std::set<Reference> seen;
    Integer total = 0;
    for (std::size_t i = 0; i < tx.inputs.size(); ++i) {
        const Reference &ref = tx.inputs[i];
        if (spent.count(ref) || seen.count(ref))
            return {"double-spend", 0};
        const auto found = utxo.find(ref);
        if (found == utxo.end())
            return {"missing-input", 0};
        const Coin &coin = found->second;
        if (!coin.mature(height, maturity))
            return {"immature", 0};
        if (tx.signatures[i] != sign(owners.at(coin.address).secret, int(i), tx.body))
            return {"bad-sig", 0};
        seen.insert(ref);
        total += coin.amount;
    }
    if (total < tx.total())
        return {"overspend", 0};
    return {"", total - tx.total()};
}
void apply(Utxo &utxo, const Transaction &tx, int height) {
    for (const Reference &ref : tx.inputs)
        utxo.erase(ref);
    for (std::size_t i = 0; i < tx.outputs.size(); ++i) {
        const Output &output = tx.outputs[i];
        utxo[{tx.id, int(i)}] = {output.first, output.second, height, tx.coinbase()};
    }
}
using Reference = std::pair<std::string, int>;
struct Coin {
    std::string address;
    Integer amount;
    int height;
    bool coinbase;
    bool mature(int, int) const;
};
using Utxo = std::map<Reference, Coin>;
struct Transaction {
    std::string text, id, body;
    std::vector<Reference> inputs;
    std::vector<Output> outputs;
    std::vector<std::string> signatures;
    int coinbase_height = -1;
    bool coinbase() const {
        return coinbase_height >= 0;
    }
    Integer size() const {
        return text.size();
    }
    Integer total() const;
};
